import { useState } from 'react'
import { toast } from 'react-toastify'
import Button from '@mui/material/Button'
import CircularProgress from '@mui/material/CircularProgress'
import PictureAsPdfOutlined from '@mui/icons-material/PictureAsPdfOutlined'
import api, { getErrorMessage } from '../../api'
import { downloadReceipt } from '../../Utils/helpers'

// "Download PDF" button for an order's receipt. The PDF is generated by the API on demand.
export default function DownloadReceiptButton({ orderId, variant = 'outlined', size = 'medium', label = 'Download PDF receipt', ...props }) {
    const [busy, setBusy] = useState(false)

    const click = async () => {
        setBusy(true)
        try {
            await downloadReceipt(api, orderId)
        } catch (err) {
            // The error body of a blob request is a Blob too, so read its text.
            let message = getErrorMessage(err, 'Could not download the receipt')
            if (err.response && err.response.data instanceof Blob) {
                try { message = JSON.parse(await err.response.data.text()).message || message } catch { /* keep default */ }
            }
            toast.error(message)
        }
        setBusy(false)
    }

    return (
        <Button
            variant={variant}
            size={size}
            onClick={click}
            disabled={busy}
            startIcon={busy ? <CircularProgress size={16} /> : <PictureAsPdfOutlined />}
            {...props}
        >
            {busy ? 'Preparing…' : label}
        </Button>
    )
}
